<?php
require_once __DIR__ . '/includes/bootstrap.php'; adminRequireLogin();
ensureMisTables();
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['update_tracking'])) {
    $orderId = (int) ($_POST['orderid'] ?? 0); $status = $_POST['status'] ?? '';
    if ($status === 'rider_assigned') adminRedirect('operations.php', 'Assign a rider from Delivery dispatch. This creates the rider task and protects the delivery audit trail.');
    if (in_array($status, array('picked_up','out_for_delivery','delivered','delivery_failed'), true)) adminRedirect('order-details.php', 'Only the assigned rider can update this delivery stage.');
    $result = $orderId > 0 ? orderTransition($orderId, $status, 'admin', $_SESSION['admin_email'], 'Updated by admin') : array(false, 'Choose an order.');
    adminRedirect('order-details.php', $result[1]);
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['verify_payment'])) {
    $orderId = (int) ($_POST['orderid'] ?? 0); $reference = trim($_POST['payment_reference'] ?? '');
    $conn = dbConnect();
    if ($orderId < 1 || $reference === '') adminRedirect('order-details.php', 'A verified provider reference is required.');
    if (!mysqli_begin_transaction($conn)) adminRedirect('order-details.php', 'Could not start payment verification.');
    $payment = mysqli_prepare($conn, "UPDATE order_payments SET payment_status='paid',reference_label=?,verified_at=NOW() WHERE orderid=? AND payment_method<>'cod' AND payment_status IN ('pending','payment_requested','authorized')");
    $ok = $payment && mysqli_stmt_bind_param($payment, 'si', $reference, $orderId) && mysqli_stmt_execute($payment) && mysqli_stmt_affected_rows($payment) === 1;
    $ok = $ok && orderAudit($conn, $orderId, 'admin', $_SESSION['admin_email'], 'payment_verified', null, 'paid', 'Provider reference: ' . $reference);
    $ok ? mysqli_commit($conn) : mysqli_rollback($conn);
    if (!$ok) adminRedirect('order-details.php', 'Payment was not eligible for verification.');
    $transition = orderTransition($orderId, 'placed', 'admin', $_SESSION['admin_email'], 'Verified online payment');
    adminRedirect('order-details.php', $transition[1]);
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['fail_payment'])) {
    $orderId = (int) ($_POST['orderid'] ?? 0); $reason = trim($_POST['payment_note'] ?? 'Payment failed'); $conn = dbConnect();
    $payment = mysqli_prepare($conn, "UPDATE order_payments SET payment_status='failed' WHERE orderid=? AND payment_method<>'cod' AND payment_status IN ('pending','payment_requested','authorized')");
    $ok = $payment && mysqli_stmt_bind_param($payment, 'i', $orderId) && mysqli_stmt_execute($payment) && mysqli_stmt_affected_rows($payment) === 1;
    if ($ok) { orderAudit($conn, $orderId, 'admin', $_SESSION['admin_email'], 'payment_failed', null, 'failed', $reason); $transition = orderTransition($orderId, 'payment_failed', 'admin', $_SESSION['admin_email'], $reason); adminRedirect('order-details.php', $transition[1]); }
    adminRedirect('order-details.php', 'Payment was not eligible to be marked failed.');
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['review_cancellation'])) {
    $orderId = (int) ($_POST['orderid'] ?? 0); $decision = $_POST['decision'] ?? ''; $note = trim($_POST['admin_note'] ?? ''); $conn = dbConnect();
    if ($orderId > 0 && in_array($decision, array('approved','rejected'), true)) {
        if ($decision === 'approved') {
            $state = mysqli_prepare($conn, 'SELECT status FROM order_tracking WHERE orderid=?'); mysqli_stmt_bind_param($state, 'i', $orderId); mysqli_stmt_execute($state);
            $stateRow = mysqli_fetch_assoc(mysqli_stmt_get_result($state));
            if (!in_array($stateRow['status'] ?? '', array('placed','confirmed'), true)) adminRedirect('order-details.php', 'This cancellation request can no longer be approved under the policy.');
        }
        $stmt = mysqli_prepare($conn, "UPDATE order_cancellations SET status=?,admin_note=?,decided_at=NOW() WHERE orderid=? AND status='requested'"); mysqli_stmt_bind_param($stmt, 'ssi', $decision, $note, $orderId); mysqli_stmt_execute($stmt);
        if ($decision === 'approved' && mysqli_stmt_affected_rows($stmt)) {
            $payment = mysqli_prepare($conn, 'SELECT p.payment_method,f.total_amount FROM order_payments p LEFT JOIN order_financials f ON f.orderid=p.orderid WHERE p.orderid=?'); mysqli_stmt_bind_param($payment, 'i', $orderId); mysqli_stmt_execute($payment); $paymentRow = mysqli_fetch_assoc(mysqli_stmt_get_result($payment));
            $refundStatus = ($paymentRow['payment_method'] ?? 'cod') === 'cod' ? 'not_required' : 'requested';
            $refundAmount = (float) ($paymentRow['total_amount'] ?? 0); $refund = mysqli_prepare($conn, 'INSERT INTO order_refunds(orderid,amount,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount),status=VALUES(status)'); mysqli_stmt_bind_param($refund, 'ids', $orderId, $refundAmount, $refundStatus); mysqli_stmt_execute($refund);
            orderTransition($orderId, 'cancelled', 'admin', $_SESSION['admin_email'], 'Cancellation approved: ' . $note);
        }
    }
    header('Location: order-details.php'); exit;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['review_item_cancellation'])) {
    $requestId = (int) ($_POST['item_cancellation_id'] ?? 0); $decision = $_POST['decision'] ?? ''; $note = trim($_POST['admin_note'] ?? ''); $conn = dbConnect();
    $request = adminRows('SELECT c.*,p.payment_method FROM order_item_cancellations c LEFT JOIN order_payments p ON p.orderid=c.orderid WHERE c.item_cancellation_id=' . $requestId . ' LIMIT 1'); $request = $request[0] ?? null;
    if ($request && $request['status'] === 'requested' && in_array($decision, array('approved','rejected'), true)) {
        $stmt = mysqli_prepare($conn, "UPDATE order_item_cancellations SET status=?,admin_note=?,decided_at=NOW(),refund_status=? WHERE item_cancellation_id=? AND status='requested'");
        $refundStatus = $decision === 'approved' && ($request['payment_method'] ?? 'cod') !== 'cod' ? 'requested' : 'not_required'; mysqli_stmt_bind_param($stmt, 'sssi', $decision, $note, $refundStatus, $requestId); mysqli_stmt_execute($stmt);
        if ($decision === 'approved' && mysqli_stmt_affected_rows($stmt)) {
            $amount = (float) $request['amount']; $financial = mysqli_prepare($conn, 'UPDATE order_financials SET subtotal=GREATEST(0,subtotal-?),total_amount=GREATEST(0,total_amount-?) WHERE orderid=?'); mysqli_stmt_bind_param($financial, 'ddi', $amount, $amount, $request['orderid']); mysqli_stmt_execute($financial);
            orderRecordStatus($conn, (int) $request['orderid'], 'item_cancelled', 'Dish cancellation approved: ' . $request['pname'], $_SESSION['admin_email']);
        }
    }
    header('Location: order-details.php'); exit;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['update_refund'])) {
    $refundId = (int) ($_POST['refund_id'] ?? 0); $status = $_POST['refund_status'] ?? ''; $reference = trim($_POST['reference_label'] ?? '');
    if ($refundId > 0 && in_array($status, array('approved','processing','processed','rejected','failed'), true)) { $stmt = mysqli_prepare(dbConnect(), 'UPDATE order_refunds SET status=?,reference_label=? WHERE refund_id=?'); mysqli_stmt_bind_param($stmt, 'ssi', $status, $reference, $refundId); mysqli_stmt_execute($stmt); }
    header('Location: order-details.php'); exit;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals(adminToken(), $_POST['csrf'] ?? '') && isset($_POST['update_item_refund'])) {
    $requestId = (int) ($_POST['item_cancellation_id'] ?? 0); $status = $_POST['refund_status'] ?? '';
    if ($requestId > 0 && in_array($status, array('approved','processing','processed','rejected','failed'), true)) { $stmt = mysqli_prepare(dbConnect(), 'UPDATE order_item_cancellations SET refund_status=? WHERE item_cancellation_id=? AND status=\'approved\''); mysqli_stmt_bind_param($stmt, 'si', $status, $requestId); mysqli_stmt_execute($stmt); }
    header('Location: order-details.php'); exit;
}
$orders = adminRows('SELECT o.orderid,o.name,o.email,o.phone,o.address,f.subtotal,f.discount_amount,f.total_amount,f.offer_code,p.payment_method,p.payment_status,t.status,t.updated_at,c.reason AS cancellation_reason,c.status AS cancellation_status,c.customer_note,r.status AS refund_status,r.amount AS refund_amount FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid LEFT JOIN order_cancellations c ON c.orderid=o.orderid LEFT JOIN order_refunds r ON r.orderid=o.orderid ORDER BY o.orderid DESC');
$items = adminRows("SELECT i.orderid,i.pname,i.pprice,i.quantity,f.category,COALESCE(NULLIF(CAST(f.picture AS CHAR),''),(SELECT g.image_path FROM site_gallery_images g WHERE g.category_name=f.category AND g.is_visible=1 ORDER BY g.sort_order,g.image_id LIMIT 1)) AS picture FROM order_items i LEFT JOIN foods f ON f.name=i.pname ORDER BY i.orderid DESC");
$itemsByOrder = array(); foreach ($items as $item) $itemsByOrder[$item['orderid']][] = $item;
$itemRequests = adminRows("SELECT c.item_cancellation_id,c.orderid,c.pname,c.quantity,c.amount,c.reason,c.customer_note,c.created_at,o.name,o.email FROM order_item_cancellations c JOIN orders o ON o.orderid=c.orderid WHERE c.status='requested' ORDER BY c.created_at ASC");
$refundRequests = adminRows("SELECT r.refund_id,r.orderid,r.amount,r.status,r.reference_label,o.name,o.email FROM order_refunds r JOIN orders o ON o.orderid=r.orderid WHERE r.status IN ('requested','approved','processing','failed') ORDER BY r.updated_at ASC");
$itemRefundRequests = adminRows("SELECT c.item_cancellation_id,c.orderid,c.pname,c.amount,c.refund_status,o.name FROM order_item_cancellations c JOIN orders o ON o.orderid=c.orderid WHERE c.status='approved' AND c.refund_status IN ('requested','approved','processing','failed') ORDER BY c.created_at ASC");
$adminTitle = 'Orders'; $adminPage = 'orders'; $adminStyles = array('workflow-tabs.css','order-modal.css','order-table.css'); include __DIR__ . '/includes/header.php';
?>
<section class="admin-card"><h2>Order history</h2><p class="admin-muted">Statuses only move forward through the configured workflow. Online payments must be verified before they reach the restaurant queue.</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ID</th><th>Customer</th><th>Contact</th><th>Delivery address</th><th>Items</th><th>Total</th><th>Payment</th><th>Tracking</th></tr></thead><tbody><?php foreach ($orders as $order) { $total = 0; ?><tr><td>#<?php echo (int) $order['orderid']; ?></td><td><?php echo adminEscape($order['name']); ?></td><td><?php echo adminEscape($order['email']); ?><br><?php echo adminEscape($order['phone']); ?></td><td><?php echo adminEscape($order['address']); ?></td><td><?php foreach ($itemsByOrder[$order['orderid']] ?? array() as $item) { $total += (int) $item['pprice'] * (int) $item['quantity']; ?><div><?php echo (int) $item['quantity']; ?> &times; <?php echo adminEscape($item['pname']); ?> (Rs <?php echo (int) $item['pprice']; ?>)</div><?php } ?></td><td><?php if ($order['total_amount'] !== null) { ?><strong>Rs <?php echo number_format((float) $order['total_amount']); ?></strong><?php if ((float) $order['discount_amount'] > 0) { ?><br><span class="admin-muted">Discount Rs <?php echo number_format((float) $order['discount_amount']); ?><?php echo $order['offer_code'] ? ' &middot; ' . adminEscape($order['offer_code']) : ''; ?></span><?php } ?><?php } else { ?>Rs <?php echo $total; ?><?php } ?></td><td><strong><?php echo adminEscape(ucwords(str_replace('_',' ', $order['payment_status'] ?? 'pending'))); ?></strong><br><span class="admin-muted"><?php echo adminEscape(ucwords($order['payment_method'] ?? '')); ?></span><?php if (($order['status'] ?? '') === 'payment_pending') { ?><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="orderid" value="<?php echo (int)$order['orderid']; ?>"><input name="payment_reference" maxlength="120" required placeholder="Verified provider reference"><button class="admin-btn" name="verify_payment" value="1">Verify</button></form><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="orderid" value="<?php echo (int)$order['orderid']; ?>"><input name="payment_note" maxlength="500" placeholder="Failure reason"><button class="admin-btn danger" name="fail_payment" value="1">Fail</button></form><?php } ?></td><td><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="orderid" value="<?php echo (int) $order['orderid']; ?>"><select name="status"><option value="placed" <?php echo ($order['status'] ?? 'placed') === 'placed' ? 'selected' : ''; ?>>Placed</option><option value="confirmed" <?php echo ($order['status'] ?? '') === 'confirmed' ? 'selected' : ''; ?>>Confirmed</option><option value="preparing" <?php echo ($order['status'] ?? '') === 'preparing' ? 'selected' : ''; ?>>Preparing</option><option value="ready_for_pickup" <?php echo ($order['status'] ?? '') === 'ready_for_pickup' ? 'selected' : ''; ?>>Ready for pickup</option><option value="rider_assigned" <?php echo ($order['status'] ?? '') === 'rider_assigned' ? 'selected' : ''; ?>>Rider assigned</option><option value="picked_up" <?php echo ($order['status'] ?? '') === 'picked_up' ? 'selected' : ''; ?>>Picked up</option><option value="out_for_delivery" <?php echo ($order['status'] ?? '') === 'out_for_delivery' ? 'selected' : ''; ?>>Out for delivery</option><option value="delivered" <?php echo ($order['status'] ?? '') === 'delivered' ? 'selected' : ''; ?>>Delivered</option><option value="completed" <?php echo ($order['status'] ?? '') === 'completed' ? 'selected' : ''; ?>>Completed</option><option value="cancelled" <?php echo ($order['status'] ?? '') === 'cancelled' ? 'selected' : ''; ?>>Cancelled</option></select><button class="admin-icon-button" name="update_tracking" title="Save tracking status" aria-label="Save tracking status"><i class="bi bi-save" aria-hidden="true"></i></button></form></td></tr><?php } ?></tbody></table><?php if (!$orders) { ?><p class="admin-muted">No orders yet.</p><?php } ?></div></section>
<section class="admin-card"><h2>Cancellation and refund requests</h2><?php $requests = array_filter($orders, function ($order) { return ($order['cancellation_status'] ?? '') === 'requested'; }); ?><?php if (!$requests) { ?><p class="admin-muted">No cancellation requests awaiting review.</p><?php } else { foreach ($requests as $order) { ?><article class="admin-comment"><strong>Order #<?php echo (int) $order['orderid']; ?> · <?php echo adminEscape($order['name']); ?></strong><p>Reason: <?php echo adminEscape($order['cancellation_reason']); ?><br>Customer note: <?php echo adminEscape($order['customer_note'] ?: 'None'); ?><br>Refund: Rs <?php echo number_format((float) ($order['refund_amount'] ?? 0)); ?> · <?php echo adminEscape($order['refund_status'] ?? 'not required'); ?></p><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="orderid" value="<?php echo (int) $order['orderid']; ?>"><input name="admin_note" maxlength="500" placeholder="Decision note"><input type="hidden" name="decision" value=""><button class="admin-btn" name="review_cancellation" value="1" type="submit" onclick="this.form.decision.value='approved'">Approve</button><button class="admin-btn danger" name="review_cancellation" value="1" type="submit" onclick="this.form.decision.value='rejected'">Reject</button></form></article><?php } } ?></section>
<section class="admin-card"><h2>Dish cancellation requests</h2><?php if (!$itemRequests) { ?><p class="admin-muted">No dish cancellation requests awaiting review.</p><?php } else { foreach ($itemRequests as $request) { ?><article class="admin-comment"><strong>Order #<?php echo (int) $request['orderid']; ?> · <?php echo adminEscape($request['name']); ?></strong><p><strong><?php echo adminEscape($request['pname']); ?></strong> · <?php echo (int) $request['quantity']; ?> item(s) · Rs <?php echo number_format((float) $request['amount']); ?><br>Reason: <?php echo adminEscape($request['reason']); ?><br>Customer note: <?php echo adminEscape($request['customer_note'] ?: 'None'); ?></p><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="item_cancellation_id" value="<?php echo (int) $request['item_cancellation_id']; ?>"><input name="admin_note" maxlength="500" placeholder="Decision note"><input type="hidden" name="decision" value=""><button class="admin-btn" name="review_item_cancellation" value="1" type="submit" onclick="this.form.decision.value='approved'">Approve</button><button class="admin-btn danger" name="review_item_cancellation" value="1" type="submit" onclick="this.form.decision.value='rejected'">Reject</button></form></article><?php } } ?></section>
<section class="admin-card"><h2>Refund queue</h2><?php if (!$refundRequests) { ?><p class="admin-muted">No refunds awaiting action.</p><?php } else { foreach ($refundRequests as $refund) { ?><article class="admin-comment"><strong>Order #<?php echo (int) $refund['orderid']; ?> · <?php echo adminEscape($refund['name']); ?></strong><p>Refund amount: Rs <?php echo number_format((float) $refund['amount']); ?> · Current status: <?php echo adminEscape(ucwords(str_replace('_', ' ', $refund['status']))); ?></p><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="refund_id" value="<?php echo (int) $refund['refund_id']; ?>"><select name="refund_status"><option value="approved" <?php echo $refund['status']==='approved'?'selected':''; ?>>Approved</option><option value="processing" <?php echo $refund['status']==='processing'?'selected':''; ?>>Processing</option><option value="processed" <?php echo $refund['status']==='processed'?'selected':''; ?>>Processed</option><option value="rejected" <?php echo $refund['status']==='rejected'?'selected':''; ?>>Rejected</option><option value="failed" <?php echo $refund['status']==='failed'?'selected':''; ?>>Failed</option></select><input name="reference_label" maxlength="120" value="<?php echo adminEscape($refund['reference_label']); ?>" placeholder="Payment reference"><button class="admin-btn" name="update_refund" value="1">Save refund</button></form></article><?php } } ?></section>
<section class="admin-card"><h2>Dish refund queue</h2><?php if (!$itemRefundRequests) { ?><p class="admin-muted">No dish refunds awaiting action.</p><?php } else { foreach ($itemRefundRequests as $refund) { ?><article class="admin-comment"><strong>Order #<?php echo (int) $refund['orderid']; ?> · <?php echo adminEscape($refund['name']); ?></strong><p><?php echo adminEscape($refund['pname']); ?> · Rs <?php echo number_format((float) $refund['amount']); ?> · <?php echo adminEscape(ucwords(str_replace('_', ' ', $refund['refund_status']))); ?></p><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="item_cancellation_id" value="<?php echo (int) $refund['item_cancellation_id']; ?>"><select name="refund_status"><option value="approved">Approved</option><option value="processing">Processing</option><option value="processed">Processed</option><option value="rejected">Rejected</option><option value="failed">Failed</option></select><button class="admin-btn" name="update_item_refund" value="1">Save refund</button></form></article><?php } } ?></section>
<script>
document.querySelectorAll('select[name="status"]').forEach(function (select) {
    [['ready_for_pickup','Ready for pickup'],['rider_assigned','Rider assigned']].forEach(function (status) {
        if (!select.querySelector('option[value="' + status[0] + '"]')) { const option=document.createElement('option'); option.value=status[0]; option.textContent=status[1]; select.insertBefore(option, select.querySelector('option[value="out_for_delivery"]')); }
    });
    if (!select.querySelector('option[value="completed"]')) { const option=document.createElement('option'); option.value='completed'; option.textContent='Completed'; select.insertBefore(option, select.querySelector('option[value="cancelled"]')); }
});
</script>
<script>
(function(){const table=document.querySelector('.admin-table'),rows=table?Array.from(table.tBodies[0].rows):[];if(!rows.length)return;const counts={all:rows.length};rows.forEach(row=>{const status=row.querySelector('select[name="status"]')?.value||'placed';row.dataset.status=status;counts[status]=(counts[status]||0)+1;});const labels={all:'All orders',placed:'Placed',confirmed:'Confirmed',preparing:'Preparing',ready_for_pickup:'Ready',rider_assigned:'Rider assigned',out_for_delivery:'Out for delivery',delivered:'Delivered',completed:'Completed',cancelled:'Cancelled'};const tabs=document.createElement('nav');tabs.className='admin-workflow-tabs';tabs.setAttribute('aria-label','Order tracking status');Object.keys(labels).forEach(status=>{if(status!=='all'&&!counts[status])return;const button=document.createElement('button');button.type='button';button.dataset.status=status;button.className=status==='all'?'is-active':'';button.innerHTML=labels[status]+' <span>'+ (counts[status]||0) +'</span>';tabs.appendChild(button);});table.closest('.admin-card').querySelector('h2').after(tabs);tabs.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;tabs.querySelectorAll('button').forEach(tab=>tab.classList.toggle('is-active',tab===button));rows.forEach(row=>row.dataset.paginationMatch=button.dataset.status==='all'||row.dataset.status===button.dataset.status?'true':'false');table.dispatchEvent(new Event('foodera-pagination-filter'));});})();
</script>
<script>
(function(){const orders=<?php echo json_encode($orders, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>,items=<?php echo json_encode($itemsByOrder, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>,table=document.querySelector('.admin-table');if(!table)return;const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));const money=value=>'Rs '+Number(value||0).toLocaleString('en-IN');const modal=document.createElement('dialog');modal.className='admin-order-modal';document.body.appendChild(modal);table.tHead.rows[0].append(Object.assign(document.createElement('th'),{textContent:'Details'}));Array.from(table.tBodies[0].rows).forEach(row=>{const orderId=Number(row.cells[0].textContent.replace(/\D/g,''));const cell=document.createElement('td'),button=document.createElement('button');button.type='button';button.className='admin-icon-button';button.title='View order details';button.setAttribute('aria-label','View order #'+orderId);button.innerHTML='<i class="bi bi-eye" aria-hidden="true"></i>';button.addEventListener('click',()=>{const order=orders.find(entry=>Number(entry.orderid)===orderId),lines=items[String(orderId)]||[];const subtotal=Number(order.subtotal||0),discount=Number(order.discount_amount||0),total=Number(order.total_amount||0);modal.innerHTML='<form method="dialog" class="admin-order-modal-head"><div><span>Order #'+orderId+'</span><h2>'+escape(order.name)+'</h2></div><button aria-label="Close order details"><i class="bi bi-x-lg" aria-hidden="true"></i></button></form><div class="admin-order-modal-meta"><span><i class="bi bi-receipt" aria-hidden="true"></i>'+escape(String(order.status||'placed').replaceAll('_',' '))+'</span><span><i class="bi bi-credit-card" aria-hidden="true"></i>'+escape(order.payment_method||'Payment pending')+'</span></div><section><h3>Items</h3><div class="admin-order-modal-items">'+lines.map(item=>'<article><div class="admin-order-modal-image">'+(item.picture?'<img src="../'+escape(item.picture)+'" alt="">':'<i class="bi bi-cup-hot" aria-hidden="true"></i>')+'</div><div><strong>'+escape(item.pname)+'</strong><small>'+escape(item.category||'Menu item')+' · '+Number(item.quantity)+' × '+money(item.pprice)+'</small></div><b>'+money(Number(item.quantity)*Number(item.pprice))+'</b></article>').join('')+'</div></section><section class="admin-order-modal-bill"><h3>Bill details</h3><p><span>Food subtotal</span><b>'+money(subtotal)+'</b></p><p><span>Offer discount'+(order.offer_code?' · '+escape(order.offer_code):'')+'</span><b class="discount">- '+money(discount)+'</b></p><p class="total"><span>Total payable</span><b>'+money(total)+'</b></p></section><section class="admin-order-modal-address"><i class="bi bi-geo-alt" aria-hidden="true"></i><div><strong>Delivery address</strong><span>'+escape(order.address)+'</span></div></section>';modal.showModal();});cell.append(button);row.append(cell);});modal.addEventListener('click',event=>{if(event.target===modal)modal.close();});})();
</script>
<script>document.querySelector('.admin-table')?.classList.add('admin-order-history-table');</script>
